with lines as (select id, service, level, latency_ms, status_code, k, value from app_logs lateral view outer explode(context) x as k, value), with_windows as (select id, service, level, latency_ms, status_code, k, value, round(status_code / sum(status_code) over (partition by service, k), 4) as status_code_share from lines where level = 'WARN'), with_windows_app_logs as (select id, service, level, corr(status_code, latency_ms) over (partition by level) as corr_status_code_latency_ms, dense_rank() over (partition by k, level order by status_code_share) as status_code_share_dense_rank from with_windows), base as (select *, lower(level) as level_lower from with_windows_app_logs where level in ('ERROR', 'DEBUG')) select case when status_code_share_dense_rank >= 7 then 'HIGH' else 'LOW' end as status_code_share_dense_rank_tier, service, round(avg(corr_status_code_latency_ms), 2) as avg_corr_status_code_latency_ms, avg(corr_status_code_latency_ms) filter (where service = 'checkout') as checkout_avg_corr_status_code_latency_ms, count(distinct id) as distinct_ids, count_if(level = 'ERROR') as error_events, percent_rank() over (partition by case when status_code_share_dense_rank >= 7 then 'HIGH' else 'LOW' end order by count_if(level = 'ERROR') desc) as error_events_percent_rank from base group by status_code_share_dense_rank_tier, service;
